  standard_cost: string
}

/** A fixed header plus its steps. Status is derived from the steps. */
export interface PlanSection {
  group: PlanGroup
  label: string
  status: StepStatus
  steps?: PlanStep[]
}

/** One line on the checklist. */
  coverage_date: string
  meets_line_stop: boolean
  risk_score: number
  rationale?: string
}

/** Historical price paid, from our own purchase history. */
export interface SupplierPriceRecord {
  supplier_id: string
  part_id: string
  as_of: string
  unit_price: string
  qty: number
  currency?: Currency
}

/** What our files say about a supplier. The baseline a claim is checked against. */
export interface SupplierRecord {
  supplier_id: string
  /** ERPNext `supplier_name` */
  supplier_name: string
  /** ISO 3166-1 alpha-2 */
  country: string
  locale?: string
  /** Never the raw number. See contracts.phone. */
