"""Transport callbacks and quote polling for outbound supplier calls.

The current workflow collects quotes through ``/flow/collect``. These routes
remain part of the HTTP interface because CALL-E can deliver a webhook and
older clients poll the transport buffer directly.
"""

from __future__ import annotations

from fastapi import APIRouter, Request
from pydantic import BaseModel

from packages.contracts.models import Quote
from supplyos_api.outreach.buffer import OUTREACH_BUFFER
from supplyos_api.outreach.normalize import normalize_result

router = APIRouter(tags=["outreach"])


class QuotesResponse(BaseModel):
    quotes: list[Quote]


@router.get("/tools/quotes", response_model=QuotesResponse)
def get_quotes(case_id: str) -> QuotesResponse:
    """Return the transport results collected for a case so far."""
    return QuotesResponse(quotes=OUTREACH_BUFFER.quotes_for(case_id))


@router.post("/calle/webhook")
async def calle_webhook(request: Request) -> dict[str, object]:
    """Accept a terminal CALL-E result without triggering webhook retries.

    A malformed result is still useful evidence: ``normalize_result`` turns it
    into a confidence-zero quote instead of rejecting the callback.
    """
    try:
        payload = await request.json()
    except Exception:
        return {"ok": True, "ignored": "unparseable body"}

    meta = payload.get("metadata", {}) if isinstance(payload, dict) else {}
    recipient_meta: dict = {}
    if isinstance(payload, dict) and isinstance(payload.get("recipient"), dict):
        recipient_meta = payload["recipient"].get("metadata", {}) or {}

    case_id = meta.get("case_id", "UNKNOWN")
    task_id = recipient_meta.get("task_id") or meta.get("task_id", "UNKNOWN")
    supplier_ref = recipient_meta.get("supplier_ref") or meta.get(
        "supplier_ref", "UNKNOWN"
    )

    quote = normalize_result(task_id, case_id, supplier_ref, payload)
    OUTREACH_BUFFER.add_quote(quote)
    OUTREACH_BUFFER.append_event(
        case_id,
        actor="calle",
        stage="quote_received",
        message=f"{supplier_ref}: " + ("quoted" if quote.available else "no quote"),
        payload={"task_id": task_id, "confidence": quote.confidence},
    )
    return {"ok": True}

